// Leases from your property system. Replace this node with your source.
// The next node keeps the leases that end in the next 60 days.
const inDays = (n) => new Date(Date.now() + n * 86400000).toISOString().slice(0, 10);
return [
  { json: { unit: '42 Sample Avenue, Apartment 3B, Springfield', tenant_name: 'Maria Garcia', tenant_email: 'maria.garcia@example.com', current_end: inDays(45), monthly_rent: '1,850', deposit: '1,800', pets_allowed: false } },
  { json: { unit: '42 Sample Avenue, Apartment 5A, Springfield', tenant_name: 'Jane Doe', tenant_email: 'jane.doe@example.com', current_end: inDays(200), monthly_rent: '2,100', deposit: '2,000', pets_allowed: true } },
];

// Keeps the leases ending in the next 60 days and builds a renewal envelope for each.
const TEMPLATE_URL = 'REPLACE_WITH_YOUR_TEMPLATE_URL'; // the stored residential-lease template
const LANDLORD = { name: 'Alex Chen', email: 'alex.chen@example.com' };
const DAY = 86400000;

const due = $input.all().filter(({ json: l }) => {
  const days = (new Date(l.current_end) - Date.now()) / DAY;
  return days >= 0 && days <= 60;
});

return due.map(({ json: lease }) => {
  const start = new Date(new Date(lease.current_end).getTime() + DAY);
  const end = new Date(start);
  end.setFullYear(end.getFullYear() + 1);
  end.setDate(end.getDate() - 1);
  const iso = (d) => d.toISOString().slice(0, 10);
  return {
    json: {
      unit: lease.unit,
      envelope: {
        title: `Lease renewal: ${lease.unit}`,
        message: 'Your lease renewal is ready to sign.',
        routing: 'sequential', // the tenant signs first, then the landlord countersigns
        metadata: { unit: lease.unit.slice(0, 1000) },
        documents: [
          {
            key: 'lease',
            url: TEMPLATE_URL,
            format: 'docx',
            data: {
              leaseDate: iso(new Date()),
              landlord: { name: LANDLORD.name },
              tenant: { name: lease.tenant_name },
              property: { address: lease.unit },
              startDate: iso(start),
              endDate: iso(end),
              currency: 'USD',
              monthlyRent: lease.monthly_rent,
              dueDay: '1',
              deposit: lease.deposit,
              petsAllowed: Boolean(lease.pets_allowed),
            },
            places: [
              { key: 'tenant_signs_here', type: 'signature', recipient_key: 'tenant' },
              { key: 'landlord_signs_here', type: 'signature', recipient_key: 'landlord' },
            ],
          },
        ],
        recipients: [
          { type: 'signer', key: 'tenant', name: lease.tenant_name, email: lease.tenant_email },
          { type: 'signer', key: 'landlord', name: LANDLORD.name, email: LANDLORD.email },
        ],
      },
    },
  };
});
